-- 第 325 枚迁移 line 114 `dp_noise_added real → boolean` 在 PG 无 real→boolean cast 路径;
-- ihui_dev 该表 0 行,`<> 0.0` 语义即迁移注释所写"0 行无数据风险"的等价收敛(非零→true)。
-- 列上还有 real 默认值 0.0(同样无法自动投 boolean),先摘默认、改型、再按 TS 权威
-- (agent-state.ts: dpNoiseAdded 默认 false)补回 boolean 默认。

ALTER TABLE "agent_federated_lessons" ALTER COLUMN "dp_noise_added" DROP DEFAULT;
ALTER TABLE "agent_federated_lessons" ALTER COLUMN "dp_noise_added" TYPE boolean USING "dp_noise_added" <> 0.0;
ALTER TABLE "agent_federated_lessons" ALTER COLUMN "dp_noise_added" SET DEFAULT false;
